  async addQuestion(question) { const data = { title:(question.title || '').trim(), questionText:question.questionText || '', questionHtml:question.questionHtml || '', questionImage:question.questionImage || '', code:String(question.code || '').trim().toUpperCase(), label:question.label || '', type:question.type || 'single', icon:question.icon || '○', options:Array.isArray(question.options) ? question.options : [], optionSettings:Array.isArray(question.optionSettings) ? question.optionSettings : [], metricUnit:question.metricUnit || '', required:question.required !== false }; if (!data.title || !data.code || !data.questionText) return { success:false, message:'Preencha a sigla, o título e o texto da pergunta.' }; const key = Date.now(); const payload = { p_token:token(), p_title:data.title, p_theme:QUESTION_THEME, p_description:encodeQuestionContent(data), p_url:`https://question.local/${key}`, p_provider:'youtube', p_embed_url:`question://${key}`, p_thumbnail_url:'' }; try { return await rpc('app_add_video', payload); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_QUESTIONS) || '[]'); const localQuestion = { id:`local-question-${key}`, title:data.title, theme:QUESTION_THEME, description:encodeQuestionContent(data), createdAt:new Date().toISOString() }; current.push(localQuestion); localStorage.setItem(DB_KEY_QUESTIONS, JSON.stringify(current)); return { success:true, question:normalizeQuestion(localQuestion) }; } },
  async updateQuestion(id, question) { const data = { title:(question.title || '').trim(), questionText:question.questionText || '', questionHtml:question.questionHtml || '', questionImage:question.questionImage || '', code:String(question.code || '').trim().toUpperCase(), label:question.label || '', type:question.type || 'single', icon:question.icon || '○', options:Array.isArray(question.options) ? question.options : [], optionSettings:Array.isArray(question.optionSettings) ? question.optionSettings : [], metricUnit:question.metricUnit || '', required:question.required !== false }; if (!data.title || !data.code || !data.questionText) return { success:false, message:'Preencha a sigla, o título e o texto da pergunta.' }; try { return await rpc('app_update_video', { p_token:token(), p_id:id, p_title:data.title, p_theme:QUESTION_THEME, p_description:encodeQuestionContent(data), p_url:`https://question.local/${id}`, p_provider:'youtube', p_embed_url:`question://${id}`, p_thumbnail_url:'' }); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_QUESTIONS) || '[]'); const index = current.findIndex(item => item.id === id); if (index < 0) return { success:false, message:'Não foi possível localizar a pergunta.' }; current[index] = { ...current[index], title:data.title, description:encodeQuestionContent(data), updatedAt:new Date().toISOString() }; localStorage.setItem(DB_KEY_QUESTIONS, JSON.stringify(current)); return { success:true, question:normalizeQuestion(current[index]) }; } },
