  async addQuiz(quiz) { const data = { title:(quiz.title || '').trim(), description:quiz.description || '', questionIds:Array.isArray(quiz.questionIds) ? quiz.questionIds : [], questionSettings:quiz.questionSettings || {}, coverText:quiz.coverText || '', active:quiz.active !== false }; if (!data.title) return { success:false, message:'Informe o título do questionário.' }; if (!data.questionIds.length) return { success:false, message:'Selecione pelo menos uma pergunta.' }; const key = Date.now(); const payload = { p_token:token(), p_title:data.title, p_theme:QUIZ_THEME, p_description:encodeQuizContent(data), p_url:`https://quiz.local/${key}`, p_provider:'youtube', p_embed_url:`quiz://${key}`, p_thumbnail_url:'' }; try { return await rpc('app_add_video', payload); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_QUIZZES) || '[]'); const localQuiz = { id:`local-quiz-${key}`, title:data.title, theme:QUIZ_THEME, description:encodeQuizContent(data), createdAt:new Date().toISOString() }; current.push(localQuiz); localStorage.setItem(DB_KEY_QUIZZES, JSON.stringify(current)); return { success:true, quiz:normalizeQuiz(localQuiz) }; } },
  async updateQuiz(id, quiz) { const data = { title:(quiz.title || '').trim(), description:quiz.description || '', questionIds:Array.isArray(quiz.questionIds) ? quiz.questionIds : [], questionSettings:quiz.questionSettings || {}, coverText:quiz.coverText || '', active:quiz.active !== false }; if (!data.title) return { success:false, message:'Informe o título do questionário.' }; if (!data.questionIds.length) return { success:false, message:'Selecione pelo menos uma pergunta.' }; try { return await rpc('app_update_video', { p_token:token(), p_id:id, p_title:data.title, p_theme:QUIZ_THEME, p_description:encodeQuizContent(data), p_url:`https://quiz.local/${id}`, p_provider:'youtube', p_embed_url:`quiz://${id}`, p_thumbnail_url:'' }); } catch { const current = JSON.parse(localStorage.getItem(DB_KEY_QUIZZES) || '[]'); const index = current.findIndex(item => item.id === id); if (index < 0) return { success:false, message:'Não foi possível localizar o questionário.' }; current[index] = { ...current[index], title:data.title, description:encodeQuizContent(data), updatedAt:new Date().toISOString() }; localStorage.setItem(DB_KEY_QUIZZES, JSON.stringify(current)); return { success:true, quiz:normalizeQuiz(current[index]) }; } },
